    const set = v => el.style.setProperty("--pz", String(Math.round(v * 1000) / 1000));
    if (!maximizar) {
      // comportamiento clásico: partir de la escala base y achicar si desborda
      let trial = base;
      set(trial);
      let g = 0;
      while (!cabe() && trial > MIN && g < 80) {
        trial -= 0.03;
        set(trial);
        g++;
      }
      return;
    }

