// ── components/calendario-centro.jsx ──
// DHARMA — Calendario del centro (coach): grilla semanal, actividades y clases asignadas
const CLAVE_CALENDARIO = "dharma-calendario-v1";
const DIAS_SEM = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const DIAS_LARGO = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"];
const MESES_CAL = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
const HORA_INI = 6; // 06:00
const HORA_FIN = 20; // 20:00
const PX_HORA = 66;
const DIAS_CHIP = ["Lu", "Ma", "Mi", "Ju", "Vi", "Sá", "Do"];
const COLORES_EV = [{
  id: "teal",
  val: "#489DA3"
}, {
  id: "tealc",
  val: "#6EC5D1"
}, {
  id: "naranja",
  val: "#E84D23"
}, {
  id: "negro",
  val: "#1C1E20"
}];
const toMin = hhmm => {
  const [h, m] = (hhmm || "0:0").split(":").map(Number);
  return h * 60 + (m || 0);
};
const toHHMM = min => String(Math.floor(min / 60)).padStart(2, "0") + ":" + String(min % 60).padStart(2, "0");
const isoDe = d => d.toISOString().slice(0, 10);
const lunesDe = d => {
  const x = new Date(d);
  const day = (x.getDay() + 6) % 7;
  x.setDate(x.getDate() - day);
  x.setHours(0, 0, 0, 0);
  return x;
};
const sumarDias = (d, n) => {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
};
const CLAVE_REGISTRO_PERSONALIZADO = "dharma-registro-personalizado-v1";
function rpCargar() {
  try {
    return JSON.parse(localStorage.getItem(CLAVE_REGISTRO_PERSONALIZADO)) || [];
  } catch (e) {
    return [];
  }
}
function rpGuardar(lista) {
  try {
    localStorage.setItem(CLAVE_REGISTRO_PERSONALIZADO, JSON.stringify(lista));
  } catch (e) {}
}
function rpDePersona(personaId) {
  return rpCargar().filter(r => r.personaId === personaId).sort((a, b) => b.fecha.localeCompare(a.fecha));
}
window.RegistroPersonalizado = {
  cargar: rpCargar,
  dePersona: rpDePersona
};

// layout de superposiciones por día
function layoutDia(eventos) {
  const evs = eventos.map(e => ({
    ...e,
    s: toMin(e.inicio),
    e2: toMin(e.fin)
  })).sort((a, b) => a.s - b.s || a.e2 - b.e2);
  const out = [];
  let cluster = [],
    clusterEnd = -1;
  const flush = () => {
    const lanes = [];
    cluster.forEach(ev => {
      let lane = lanes.findIndex(end => end <= ev.s);
      if (lane === -1) {
        lane = lanes.length;
        lanes.push(ev.e2);
      } else lanes[lane] = ev.e2;
      ev.lane = lane;
    });
    cluster.forEach(ev => {
      ev.lanes = lanes.length;
      out.push(ev);
    });
    cluster = [];
    clusterEnd = -1;
  };
  evs.forEach(ev => {
    if (cluster.length && ev.s >= clusterEnd) flush();
    cluster.push(ev);
    clusterEnd = Math.max(clusterEnd, ev.e2);
  });
  flush();
  return out;
}

