/* ---------- ALERTAS DE WELLNESS (reutilizable por coach) ---------- */
function calcularAlertasWellness(wellness) {
  if (!wellness || wellness.length === 0) return {
    alertas: [],
    ultima: null
  };
  const ord = [...wellness].sort((a, b) => a.fecha < b.fecha ? 1 : -1);
  const u = ord[0];
  const previos = ord.slice(1, 8);
  const avg = k => prom(previos.map(e => Number(e[k])).filter(x => !isNaN(x)));
  const alertas = [];
  const sue = Number(u.sueno);
  if (!isNaN(sue)) {
    const a = avg("sueno");
    if (sue < 6) alertas.push({
      nivel: "alta",
      texto: "Durmió poco (" + sue + " h)"
    });else if (a != null && sue <= a - 1.5) alertas.push({
      nivel: "media",
      texto: "Sueño por debajo de su media"
    });
  }
  const chequear = (k, label, dir) => {
    const v = Number(u[k]);
    if (isNaN(v)) return;
    const a = avg(k);
    if (dir === "bajo") {
      if (v <= 2) alertas.push({
        nivel: "media",
        texto: label + " baja/o"
      });else if (a != null && v <= a - 1.5) alertas.push({
        nivel: "media",
        texto: label + " por debajo de su media"
      });
    } else {
      if (v >= 4) alertas.push({
        nivel: v >= 5 ? "alta" : "media",
        texto: label + " alto"
      });else if (a != null && v >= a + 1.5) alertas.push({
        nivel: "media",
        texto: label + " sobre su media"
      });
    }
  };
  chequear("energia", "Energía", "bajo");
  chequear("animo", "Ánimo", "bajo");
  chequear("dolor", "Dolor muscular", "alto");
  chequear("estres", "Estrés", "alto");
  return {
    alertas,
    ultima: u
  };
}

