/* ---------- migración: las cargas viejas (persona.cargas, en libras) pasan una sola vez
   al sistema de PRs (kg) la primera vez que se calcula el progreso, para no perder nada
   al retirar la pantalla vieja de "Cargas" ---------- */
function migrarCargasViejas(persona) {
  const viejas = persona.cargas || [];
  if (!viejas.length) return;
  const yaMigrado = (() => {
    try {
      return JSON.parse(localStorage.getItem("dharma-cargas-migradas-v1") || "[]");
    } catch (e) {
      return [];
    }
  })();
  if (yaMigrado.includes(persona.id)) return;
  const kgDeLb = lb => Math.round(lb * 0.453592 * 10) / 10;
  viejas.forEach(r => {
    window.Gamif.agregarPR(persona.id, {
      ejercicio: r.ejercicio,
      pilar: "fuerza",
      peso: kgDeLb(r.peso),
      reps: r.reps,
      comentario: "Migrado del registro anterior (RPE " + r.rpe + ")",
      fechaForzada: r.fecha
    });
  });
  try {
    localStorage.setItem("dharma-cargas-migradas-v1", JSON.stringify([...yaMigrado, persona.id]));
  } catch (e) {}
}
Object.assign(window, {
  AlumnoSeguimiento,
  calcularAlertasWellness,
  migrarCargasViejas
});

